<?php require_once __DIR__.'/includes/auth.php';$page_title='Requests';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=in_array($_POST['status']??'', ['APPROVED','REJECTED','COMPLETED'],true)?$_POST['status']:'REJECTED';$s=db()->prepare('SELECT * FROM demo_transactions WHERE id=?');$s->execute([$id]);$r=$s->fetch();if($r&&$r['status']==='PENDING'){db()->prepare('UPDATE demo_transactions SET status=?,reviewed_at=NOW(),reviewed_by=? WHERE id=?')->execute([$status,$admin['id'],$id]);if($status==='APPROVED'&&$r['type']==='DEPOSIT')db()->prepare('UPDATE wallets SET balance=balance+? WHERE user_id=?')->execute([$r['amount'],$r['user_id']]);if(in_array($status,['APPROVED','COMPLETED'],true)&&$r['type']==='WITHDRAWAL')db()->prepare('UPDATE wallets SET balance=GREATEST(balance-?,0),total_withdrawn=total_withdrawn+? WHERE user_id=?')->execute([$r['amount'],$r['amount'],$r['user_id']]);log_activity('Request reviewed',(int)$admin['id'],['request_id'=>$id,'status'=>$status]);flash('success','Request status updated.');}go('requests.php');}$rows=db()->query('SELECT t.*,u.username FROM demo_transactions t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>Requests</h1><p>Review simulated deposits and withdrawals.</p></div></div><div class="notice">These actions update local simulated records only. No real-money transfer occurs.</div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>USER</th><th>TYPE</th><th>AMOUNT</th><th>METHOD</th><th>DATE</th><th>STATUS</th><th>REVIEW</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['username'])?></td><td><?=e($r['type'])?></td><td><?=money($r['amount'])?></td><td><?=e($r['payment_method'])?></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td><td><span class="status <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><?php if($r['status']==='PENDING'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="button button-green" name="status" value="APPROVED">APPROVE</button> <button class="button button-danger" name="status" value="REJECTED">REJECT</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php';?>
